reference_models.verified_skeleton:
model <SystemName>
  package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater;
  inner Modelica.Fluid.System system(energyDynamics = Modelica.Fluid.Types.Dynamics.FixedInitial);

  Modelica.Fluid.Sources.Boundary_pT source(
    redeclare package Medium = Medium, p = 2.5e6, nPorts = 1, T = system.T_ambient);
  Modelica.Fluid.Valves.ValveDiscrete valve1(
    redeclare package Medium = Medium, m_flow_nominal = 40, dp_nominal = 100000);
  Modelica.Fluid.Vessels.OpenTank tank1(
    redeclare package Medium = Medium,
    crossArea = 6, height = 4, level_start = 0.05, nPorts = 2,
    portsData = {Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter = 0.2, height = 4, zeta_out = 0, zeta_in = 1),
                 Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter = 0.2, height = 0, zeta_out = 0, zeta_in = 1)});
  Modelica.Fluid.Valves.ValveDiscrete valve2(
    redeclare package Medium = Medium, m_flow_nominal = 100, dp_nominal = 1);
  Modelica.Fluid.Sources.Boundary_pT ambient1(
    redeclare package Medium = Medium, nPorts = 1, p = system.p_ambient, T = system.T_ambient);

  Modelica.Blocks.Sources.RealExpression level1(y = tank1.level);
equation
  connect(source.ports[1], valve1.port_a);
  connect(valve1.port_b, tank1.ports[1]);
  connect(tank1.ports[2], valve2.port_a);
  connect(valve2.port_b, tank2.ports[1]);
  connect(valve3.port_b, ambient1.ports[1]);
  connect(level1.y, controller.level1);
  connect(controller.valve1, valve1.open);
end <SystemName>;
